package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceRestSwapController;import com.rpb.reservation.workforce.scheduling.restswap.*;import com.rpb.reservation.walkin.api.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;
class WorkforceRestSwapApiTest {
 CurrentActorProvider actors=mock(CurrentActorProvider.class);RestSwapPlanService plans=mock(RestSwapPlanService.class);RestSwapService service=mock(RestSwapService.class);MockMvc mvc=MockMvcBuilders.standaloneSetup(new WorkforceRestSwapController(actors,plans,service)).build();String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce/rest-swaps";
 @Test void unauthenticatedAndCrossSiteWritesAreRejectedWithoutServiceCalls()throws Exception{mvc.perform(put(base+"/preview").contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(put(base+"/preview").header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","private, no-store"));mvc.perform(put(base+"/"+UUID.randomUUID()).header("X-RPB-Workforce","1").header("Sec-Fetch-Site","cross-site").contentType("application/json").content("{}")).andExpect(status().isForbidden());verifyNoInteractions(plans,service);}
 @Test void validRequestsUseExistingActorAndStoreContract()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));mvc.perform(put(base+"/preview").header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","private, no-store"));verify(plans).preview(any(),any(),any());}
}
